from datetime import date,time,datetime,timedeltahoy = date.today()print(hoy)# Fecha completa, si falta mes/dia no funciona.cumple = date(2004, 4, 1)print(cumple)# Fecha y tiempo de ahora#%A es el dia de la semana en letras#%w es el dia de la semana numerco#%d es el dia#%m es el mes#%y es el año en corto, en mayus es el completo#%H para hora#%M para minuto#%S para minutoahora = datetime.now().strftime("%d/%m/%Y %H:%M:%S")print(ahora)# Hora exacta que queremos representarhoraExacta = time(14,3,2)#Fecha y hora/minuto que queremos ponercitaMedico = datetime(2026,2,11,14,56)print(citaMedico)#Formatear fecha y hora.citaFormateada = citaMedico.strftime("%d/%m/%Y %H:%M:%S")print(citaFormateada)#/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////#Para inputs relacionados con las fechasfecha = ("01/02/2026")fecha1 = ("01/03/2026")#Aqui ponemos el formato en la que se introduce la fecha.objetoFecha = datetime.strptime(fecha, "%d/%m/%Y")print(objetoFecha)#Comparacionesif fecha < fecha1:    print(fecha,"es antes que",fecha1)#Operaciones con fecha, con timedelta podemos poner weeks, days, lo que queramos vayadentroDe67Dias = hoy + timedelta(weeks=2)print(dentroDe67Dias)print(dentroDe67Dias)